
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_mohlyp2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_mohlyp2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.433330865986797e+00, -4.346196736008691e+00, -4.224242697567457e+00, -4.055620865363366e+00, -3.826570820829310e+00, -3.523426593701434e+00, -3.137480637397395e+00, -2.674607997064805e+00, -2.170372262185986e+00, -1.689512324859887e+00, -1.189115563758080e+00, -7.457516221794743e-01, -6.376095855258771e-01, -5.207962951611645e-01, -3.854623423795599e-01, -2.763828325804099e-01, -1.891192689743974e-01, -8.197415738771448e-02, -1.823228861741876e-02, -2.049896807647097e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


